1805	fn build_router() -> ToolRouter<Handler> {
1806	    let mut router = ToolRouter::<Handler>::new();
1807	    for def in TOOL_SURFACE {
1808	        let name: &'static str = def.name;
1809	        let schema_obj = match (def.schema_fn)() {
