1821	/// Route an incoming tool call to its impl on [`Handler`].
1822	///
1823	/// Pulls the `http::request::Parts` extension that `main.rs` injects per
1824	/// request, deserializes the JSON arguments into the tool's `Parameters<T>`
1825	/// type from `panopt_tool_surface::params`, then calls the corresponding
1826	/// async method on `Handler`. The `match` over [`Tool`] is exhaustive, so the
1827	/// compiler rejects a new tool added without a dispatch arm.
1828	async fn dispatch_local<'a>(
1829	    name: &'static str,
1830	    ctx: ToolCallContext<'a, Handler>,
1831	) -> Result<CallToolResult, McpError> {
1832	    let tool = Tool::from_name(name)
1833	        .ok_or_else(|| McpError::invalid_params(format!("unknown tool `{name}`"), None))?;
1834	    let parts = ctx
1835	        .request_context
1836	        .extensions
1837	        .get::<Parts>()
1838	        .cloned()
1839	        .ok_or_else(|| {
1840	            McpError::internal_error(
1841	                "the request is missing its http::request::Parts extension",
1842	                None,
1843	            )
1844	        })?;
1845	    let handler = ctx.service;
1846	    let raw_args = ctx.arguments.unwrap_or_default();
1847	    match tool {
1848	        Tool::Identify => {
1849	            let args: IdentifyArgs = parse_json_object(raw_args)?;
1850	            handler.identify(parts, args).await
1851	        }
1852	        Tool::AgentLeave => handler.agent_leave(parts).await,
1853	        Tool::Whoami => handler.whoami(parts).await,
1854	        Tool::AgentList => handler.agent_list(parts).await,
1855	        Tool::LockAcquire => {
1856	            let args: LockAcquireArgs = parse_json_object(raw_args)?;
1857	            handler.lock_acquire(parts, args).await
1858	        }
1859	        Tool::LockRelease => {
1860	            let args: LockReleaseArgs = parse_json_object(raw_args)?;
1861	            handler.lock_release(parts, args).await
1862	        }
1863	        Tool::LockStatus => handler.lock_status(parts).await,
1864	        Tool::NoteCreate => {
1865	            let args: NoteCreateArgs = parse_json_object(raw_args)?;
1866	            handler.note_create(parts, args).await
1867	        }
