/// diff it against the render clock without parsing.
fn apply_v13(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(conn, "processes", "state_since", "INTEGER")
}

/// Version 14: `system_prompt` on agent_tools (todo #140).
///
/// A per-config system prompt the cockpit's agent-config form edits and a
/// spawn-spec template can land into a launch flag or file. Stored on the
/// durable config (the slot), not the instance, so it persists across runs.
/// `NOT NULL DEFAULT ''` keeps every existing row valid with an empty prompt.
fn apply_v14(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(
        conn,
        "agent_tools",
        "system_prompt",
        "TEXT NOT NULL DEFAULT ''",
    )
}

/// Version 15: `extra_args` on processes (todo #159).
///
/// A JSON array of per-launch extra arguments the orchestration spawn surface
/// (`spawn_agent`/`process_start`) records on the *instance* row, appended to
/// the rendered spawn argv by the edge without ever mutating the source
/// `agent_tools` config (copy-on-spawn, DESIGN S6.6). `NOT NULL DEFAULT '[]'`
/// keeps every existing process row valid with no extra args.
fn apply_v15(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(
        conn,
        "processes",
        "extra_args",
        "TEXT NOT NULL DEFAULT '[]'",
    )
}

/// Version 16: the `process_inputs` queue (todo #160).
///
/// A durable, ordered queue of input lines bound for a running instance's pane.
/// `send_input` (and an ad-hoc spawn's opening prompt) inserts a row; the daemon
/// projects undelivered rows to `.panopt/.cockpit/inputs.jsonl`; the cockpit
/// plugin writes each into the owned pane and acks it (stamping `delivered_at`),
/// after which it drops from the projection. The global `AUTOINCREMENT` id is
/// both the delivery order and the ack key, and is deliberately *not* the unified
/// per-project `next_id` - queued input is not a `#N`-addressable resource.
fn apply_v16(conn: &Connection) -> Result<(), rusqlite::Error> {
    if table_exists(conn, "process_inputs")? {
        return Ok(());
    }
    conn.execute_batch(
        "CREATE TABLE process_inputs (
             id           INTEGER PRIMARY KEY AUTOINCREMENT,
             project_id   INTEGER NOT NULL REFERENCES projects(id),
             process_id   INTEGER NOT NULL,
             content      TEXT    NOT NULL,
             created_at   TEXT    NOT NULL,
             delivered_at TEXT
         );",
    )
}

    /// `process_stop` (which writes `STOPPED`) does not cover.
    pub const EXITED: &str = "exited";
}

/// A durable, per-project agent configuration: the "what to launch" half of
/// the two-layer process model (todo #27). One tool can back many running
/// [`Process`] instances. Modeled on a row of Solo's `agent_tools` table.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct AgentTool {
    /// Numeric id, unique within the project, drawn from the unified
    /// `projects.next_id` counter (todo #16).
    pub id: u64,
    /// Identifier-style name (e.g. "claude").
    pub name: String,
    /// Optional human label for the cockpit; falls back to `name` when empty.
    pub display_name: String,
    /// The shell command this tool launches when used to spawn a process.
    pub command: String,
    /// Working directory passed to the launched command; empty means the
    /// project root.
    pub cwd: String,
    /// Free-form tag for future categorization (Solo carries one per tool).
    /// Defaults to `"agent"`.
    pub tool_type: String,
    /// A per-config system prompt the spawn-spec template can land into a
    /// launch flag or file (todo #140). Empty means "use the agent's default".
    pub system_prompt: String,
    /// Whether the tool is offered in spawn UIs. Stored but not yet enforced
    /// (no spawn UI exists in PANopt yet).
    pub enabled: bool,
    /// Sort key within the project's agent tools.
    pub position: i64,
    /// SQLite `datetime('now')` text (UTC).
    pub created_at: String,
}

/// A set of optional edits to an [`AgentTool`], applied by
/// [`crate::Store::agent_tool_update`]. Each `None` field is left untouched.
#[derive(Debug, Default, Clone)]
pub struct AgentToolPatch {
    pub name: Option<String>,
    pub display_name: Option<String>,
    pub command: Option<String>,
    pub cwd: Option<String>,
    pub tool_type: Option<String>,
    pub system_prompt: Option<String>,
    pub enabled: Option<bool>,
    pub position: Option<i64>,
}

/// A per-project process instance: the "what's running" half of the
/// two-layer model (todo #27). Carries an optional back-reference to its
/// source [`AgentTool`] when `kind` is `Agent`, plus nullable lifecycle
/// columns reserved for a follow-up that wires spawn ownership.
///
/// Whether the process is currently alive is still *not* stored - the cockpit
/// continues to derive that from live Zellij pane state until panoptd owns
/// the spawn lifecycle (DESIGN.md S10).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Process {
    /// Numeric id, unique within the project, drawn from the unified
    /// `projects.next_id` counter.
    pub id: u64,
    pub kind: ProcessKind,
    /// Identifier-style name. Empty rows fall back to the linked tool's name
    /// at projection time.
    pub name: String,
    /// Optional human label for the cockpit; falls back to `name` when empty.
    pub display_name: String,
    /// The shell command this process executes. For agent kinds this is
    /// copied from the source [`AgentTool`] at spawn time so post-spawn edits
    /// to the tool don't perturb the running instance.
    pub command: String,
    /// Working directory; empty means the project root.
    pub cwd: String,

