2103	    /// (`reconciled_panes` guards the gap before the new pane shows up in the
2104	    /// manifest), and only by the Todos gatekeeper, so a single start yields a
2105	    /// single pane rather than one per plugin instance.
2106	    ///
2107	    /// Stop is deliberately *not* reconciled: `process_stop` kills the process
2108	    /// and leaves the pane standing (the plugin never closes panes), so a
2109	    /// `stopped` row needs no pane action.
2110	    fn reconcile_starting_processes(&mut self) {
2111	        if self.mode != Mode::Todos || !self.permitted {
2112	            return;
2113	        }
2114	        // Prune entries whose row is gone. A stopped instance restarts under a
2115	        // fresh id (the daemon never reuses one), so a pruned id never returns.
2116	        let live: Vec<u64> = self.processes.iter().map(|r| r.id).collect();
2117	        self.reconciled_panes.retain(|id, _| live.contains(id));
2118	
2119	        let starting: Vec<u64> = self
2120	            .processes
2121	            .iter()
2122	            .filter(|r| r.status.as_deref() == Some("starting"))
2123	            .map(|r| r.id)
2124	            .collect();
2125	        for id in starting {
2126	            if self.reconciled_panes.contains_key(&id) || self.process_pane(id).is_some() {
2127	                continue;
2128	            }
2129	            let id_str = id.to_string();
2130	            let args = vec![
2131	                "_process-run".to_string(),
2132	                "--port".to_string(),
2133	                self.port.clone(),
2134	                id_str.clone(),
2135	            ];
2136	            // Reconcile in the background - a new instance appearing must not
2137	            // yank keyboard focus off whatever pane the user is in.
2138	            if let Some(PaneId::Terminal(tid)) = self.spawn_in_slot(args, false) {
2139	                self.reconciled_panes.insert(id, tid);
2140	                // Hand the daemon the pane the instance landed in. The pid is
2141	                // reported separately by the in-pane shim; this is best-effort.
2142	                if let Some(cwd) = self.launch_cwd() {
2143	                    let tid_str = tid.to_string();
2144	                    self.run_panopt(
2145	                        &[
2146	                            "_process-report",
2147	                            "--port",
2148	                            self.port.as_str(),
2149	                            "--id",
2150	                            id_str.as_str(),
2151	                            "--pane-id",
2152	                            tid_str.as_str(),
2153	                        ],
2154	                        cwd,
2155	                    );
2156	                }
2157	            }
2158	        }
2159	    }
